#!/bin/bash
#SBATCH --job-name=@@JOB_NAME@@
#SBATCH --nodes=@@NODES@@
#SBATCH --ntasks-per-node=@@RANKS@@
#SBATCH --cpus-per-task=@@THREADS@@
#SBATCH --exclusive
#SBATCH --no-requeue
#SBATCH --time=@@WALL@@
#SBATCH --output=logs/@@JOB_NAME@@.%j.out
#SBATCH --error=logs/@@JOB_NAME@@.%j.out
@@SBATCH_LINES@@
# Generated by testsuite/lowrank/campaign/make_campaign.py from job_template_packed.sh -- do not edit (regenerate instead).
# PACKED JOB (description key pack_nodes > 1): one job = @@NODES@@ node slots of one layout, every slot a queue of runs
# (any point / L / scheme / N_delay / repetition) executed one after the other on its own node; all slots run
# concurrently, each slot is a background subshell, the job waits for all of them. bash 3.2, no python.
# Slot i runs on host i of `scontrol show hostnames "$SLURM_JOB_NODELIST"` through the profile's profile_launch_on.
# Submitted from the campaign directory (submit_all.sh), so SLURM_SUBMIT_DIR is the campaign directory.
# Never deletes anything: each execution of a run gets a fresh attempt directory runs/<run_id>/a<k>.
# Status per run (runs/<run_id>/status, first word): OK | FAILED rc=... | INVALID pinning ... | NOT_RUN ... | RUNNING;
# written by the slot's run loop and, for an interrupted run, by the slot's EXIT trap (time limit: SIGTERM -> FAILED
# rc=143); runs a slot does not reach become NOT_RUN unless an earlier job left FAILED/INVALID (kept). A failing run or
# slot never stops the other slots: a slot that cannot start (node provenance, host check, MKL probe) marks only its own
# runs NOT_RUN. Job level (binary / build info mismatch, profile_setup) aborts everything before any slot starts.
# The per-run block below is the one of job_template.sh (one node per job) with HOST / slot added: keep them in sync.

CAMPAIGN_ID='@@CAMPAIGN_ID@@'
JOB_NAME='@@JOB_NAME@@'
RANKS=@@RANKS@@
THREADS=@@THREADS@@
NSLOTS=@@NODES@@
FAKEINTEL='@@FAKEINTEL@@'
BINARY='@@BINARY@@'
BINARY_SHA256='@@BINARY_SHA256@@'
BUILD_INFO='@@BUILD_INFO@@'
MAX_ATTEMPTS=@@MAX_ATTEMPTS@@
# slot run_id scheme n_delay   (slot i runs on host i; order within a slot: rotated by the repetition)
RUNS='@@RUNS@@'

C="${SLURM_SUBMIT_DIR:-$PWD}"
if ! grep -q "\"campaign_id\": \"$CAMPAIGN_ID\"" "$C/campaign.json" 2>/dev/null; then
    echo "job $JOB_NAME: $C is not the directory of campaign $CAMPAIGN_ID (submit from the campaign directory)" >&2
    exit 2
fi
. "$C/scripts/profile.sh"
. "$C/scripts/provenance.sh"

log() { echo "[$(date '+%Y-%m-%dT%H:%M:%S')] $JOB_NAME: $*"; }

JOBDIR="$C/jobs/$JOB_NAME/job_${SLURM_JOB_ID:-pid$$}"
k=1; base="$JOBDIR"; while [ -e "$JOBDIR" ]; do k=$((k + 1)); JOBDIR="${base}_$k"; done
mkdir -p "$JOBDIR"
JOBREL="${JOBDIR#$C/}"

ALL_RIDS="$(printf '%s\n' "$RUNS" | awk 'NF {print $2}')"
DONE_RUNS=" "
JOB_RC=0
JOB_SIGNAL=""
SLOTS_STARTED=0
SLOT_PIDS=""
HOSTS=""

set_status() {   # set_status RUN_DIR LINE
    echo "$2" > "$1/status"
    echo "$(date '+%Y-%m-%dT%H:%M:%S') job=${SLURM_JOB_ID:-}${SLOT:+ slot=$SLOT} $2" >> "$1/status.history"
}

# not_reached RC SIGNAL WHO < "run_id ..." lines: runs that were not reached become NOT_RUN; FAILED / INVALID from an
# earlier job are kept (history note only); skipped / finished runs are in DONE_RUNS
not_reached() {
    local rc="$1" sig="$2" who="$3" rid rest
    while read -r rid rest; do
        [ -n "$rid" ] || continue
        case "$DONE_RUNS" in *" $rid "*) continue ;; esac
        case "$(awk '{print $1; exit}' "$C/runs/$rid/status" 2>/dev/null)" in
            OK) ;;
            FAILED|INVALID)   # keep the earlier result (not reached); history only
                echo "$(date '+%Y-%m-%dT%H:%M:%S') job=${SLURM_JOB_ID:-} not reached (rc=$rc ${sig}), status kept" \
                    >> "$C/runs/$rid/status.history" ;;
            *) set_status "$C/runs/$rid" "NOT_RUN ($who ended before this run, rc=$rc ${sig})" ;;
        esac
    done
}

host_of() { printf '%s\n' "$HOSTS" | sed -n "$(($1 + 1))p"; }
slot_runs() { printf '%s\n' "$RUNS" | awk -v s="$1" 'NF && $1 == s {print $2, $3, $4}'; }

# slot_report: one status line per slot (also in job.status): rc of the slot and the status of its runs
slot_report() {
    local i=0 d rc ok fl inv nr n rid
    while [ "$i" -lt "$NSLOTS" ]; do
        d="$JOBDIR/slot_$i"
        rc="$(cat "$d/slot.rc" 2>/dev/null)"; [ -n "$rc" ] || rc="unknown"
        ok=0; fl=0; inv=0; nr=0; n=0
        for rid in $(printf '%s\n' "$RUNS" | awk -v s="$i" 'NF && $1 == s {print $2}'); do
            n=$((n + 1))
            case "$(awk '{print $1; exit}' "$C/runs/$rid/status" 2>/dev/null)" in
                OK) ok=$((ok + 1)) ;; FAILED) fl=$((fl + 1)) ;; INVALID) inv=$((inv + 1)) ;; *) nr=$((nr + 1)) ;;
            esac
        done
        echo "slot $i host=$(host_of "$i") rc=$rc runs=$n ok=$ok failed=$fl invalid=$inv not_run=$nr" | tee -a "$JOBDIR/job.status"
        i=$((i + 1))
    done
}

on_exit() {
    local rc="$1"
    trap - EXIT TERM INT
    echo "rc=$rc ${JOB_SIGNAL}" > "$JOBDIR/job.status"
    if [ "$SLOTS_STARTED" = 0 ]; then       # aborted before any slot: all runs of the job were not reached
        not_reached "$rc" "$JOB_SIGNAL" "job ${SLURM_JOB_ID:-}" <<EOF
$ALL_RIDS
EOF
    else
        slot_report
    fi
    log "end rc=$rc ${JOB_SIGNAL}"
    exit "$rc"
}
wait_slots() { local p; for p in $SLOT_PIDS; do wait "$p"; done; }
trap 'on_exit $?' EXIT
trap 'JOB_SIGNAL=SIGTERM; for p in $SLOT_PIDS; do kill -TERM "$p" 2>/dev/null; done; wait_slots; exit 143' TERM
trap 'JOB_SIGNAL=SIGINT; for p in $SLOT_PIDS; do kill -TERM "$p" 2>/dev/null; done; wait_slots; exit 130' INT

job_abort() { log "ABORT: $1"; echo "$1" > "$JOBDIR/abort_reason.txt"; exit "${2:-3}"; }

log "start in $C, job dir $JOBREL, $NSLOTS slots"
# ---- environment of every run (MKL_NUM_THREADS = OMP_NUM_THREADS; MKL_VERBOSE only in the probe) ----------------------
export OMP_NUM_THREADS="$THREADS" MKL_NUM_THREADS="$THREADS" MKL_DYNAMIC=FALSE
export OMP_DISPLAY_AFFINITY=TRUE OMP_AFFINITY_FORMAT='OMP_AFFINITY host=%H pid=%P thread=%n affinity=%A'
unset MKL_VERBOSE LD_PRELOAD
export FAKEINTEL FAKEINTEL_LIB TIME_STYLE PROV_SYSFS_ROOT PROV_PROC_ROOT
profile_setup || job_abort "profile_setup failed"

# ---- binary and build provenance (once; the binary lives on the shared workspace file system) -------------------------
[ -x "$BINARY" ] || job_abort "binary $BINARY not executable"
[ -r "$BUILD_INFO" ] || job_abort "build info $BUILD_INFO missing (run build_info.sh after the build)"
bin_sha="$(prov_sha256 "$BINARY")"
[ "$bin_sha" = "$(sed -n 's/^binary_sha256=//p' "$BUILD_INFO")" ] || job_abort "binary sha256 $bin_sha differs from $BUILD_INFO"
[ -z "$BINARY_SHA256" ] || [ "$bin_sha" = "$BINARY_SHA256" ] || job_abort "binary sha256 $bin_sha differs from the campaign's $BINARY_SHA256"

# ---- hosts: slot i runs on host i ------------------------------------------------------------------------------------
[ -n "${SLURM_JOB_NODELIST:-}" ] || job_abort "SLURM_JOB_NODELIST is empty (not inside a Slurm job?)"
HOSTS="$(scontrol show hostnames "$SLURM_JOB_NODELIST" 2>/dev/null)"
nhosts="$(printf '%s\n' "$HOSTS" | grep -c .)"
[ "$nhosts" -ge "$NSLOTS" ] || job_abort "scontrol show hostnames '$SLURM_JOB_NODELIST' gave $nhosts hosts for $NSLOTS slots"

# ---- job provenance (once; the node-level part follows per host in the slots) ----------------------------------------
F="$JOBDIR/job.prov"
prov_job_common "$JOBDIR" "$F" || job_abort "prov_job_common failed"
prov_job_env "$JOBDIR" "$F"
prov_kv "$F" ranks "$RANKS"
prov_kv "$F" threads "$THREADS"
prov_kv "$F" packed_slots "$NSLOTS"
prov_kv "$F" packed_hosts "$(printf '%s\n' "$HOSTS" | sed -n "1,${NSLOTS}p" | tr '\n' ' ')"
prov_kv "$F" batch_host "${SLURMD_NODENAME:-$(hostname)}"
prov_kv "$F" job_script_sha256 "$(prov_sha256 "$C/jobs/$JOB_NAME.sbatch")"
prov_kv "$F" profile_sha256 "$(prov_sha256 "$C/scripts/profile.sh")"
prov_kv "$F" provenance_sh_sha256 "$(prov_sha256 "$C/scripts/provenance.sh")"
prov_kv "$F" rank_wrap_sha256 "$(prov_sha256 "$C/scripts/rank_wrap.sh")"
prov_kv "$F" node_prov_sha256 "$(prov_sha256 "$C/scripts/node_prov.sh")"
prov_kv "$F" binary "$BINARY"
prov_kv "$F" binary_sha256 "$bin_sha"
prov_kv "$F" build_info "$BUILD_INFO"
prov_kv "$F" build_info_sha256 "$(prov_sha256 "$BUILD_INFO")"
while IFS= read -r line; do
    case "$line" in
        "### "*) break ;;
        *=*) prov_kv "$F" "build_${line%%=*}" "${line#*=}" || job_abort "bad build info line: $line" ;;
    esac
done < "$BUILD_INFO"
prov_kv "$F" fakeintel "$FAKEINTEL"
case "$(sed -n 's/^link_type=//p' "$BUILD_INFO")" in
    static*) [ "$FAKEINTEL" = on ] && job_abort "fakeintel=on but the binary is statically linked (LD_PRELOAD cannot act)" ;;
esac
if [ "$FAKEINTEL" = on ]; then
    prov_kv "$F" fakeintel_lib "$FAKEINTEL_LIB"
    prov_kv "$F" fakeintel_lib_sha256 "$(prov_sha256 "$FAKEINTEL_LIB")"
else
    prov_kv "$F" fakeintel_lib "n/a (fakeintel off)"
    prov_kv "$F" fakeintel_lib_sha256 "n/a (fakeintel off)"
fi

# ---- slots -----------------------------------------------------------------------------------------------------------
slog() { log "slot $SLOT ($HOST): $*"; }

kill_tree() { local c; for c in $(pgrep -P "$1" 2>/dev/null); do kill_tree "$c"; done; kill -TERM "$1" 2>/dev/null; }
kill_launch() { [ -n "$LP" ] || return 0; kill_tree "$LP"; wait "$LP" 2>/dev/null; LP=""; }
# lrun CMD ...: CMD in a background subshell, waited for (so that the slot's TERM trap acts at once); status in LRC
lrun() { "$@" & LP=$!; wait "$LP"; LRC=$?; LP=""; }
in_dir() { local d="$1"; shift; cd "$d" && "$@"; }

slot_exit() {
    local rc="$1"
    trap - EXIT TERM INT
    if [ -n "$CURRENT_RUN" ]; then
        set_status "$CURRENT_RUN" "FAILED rc=$rc (job ended during the run: ${SLOT_SIGNAL:-exit})"
    fi
    not_reached "$rc" "$SLOT_SIGNAL" "job ${SLURM_JOB_ID:-} slot $SLOT" <<EOF
$MY_RUNS
EOF
    echo "$rc" > "$SLOTDIR/slot.rc"
    slog "end rc=$rc ${SLOT_SIGNAL}"
    exit "$rc"
}
slot_abort() { slog "ABORT: $1"; echo "$1" > "$SLOTDIR/abort_reason.txt"; exit "${2:-3}"; }

# run_slot INDEX HOST: started in the background (own subshell); always ends with an explicit exit (EXIT trap)
run_slot() {
    SLOT="$1"; HOST="$2"
    trap - EXIT TERM INT
    SLOTDIR="$JOBDIR/slot_$SLOT"; SLOTREL="${SLOTDIR#$C/}"
    mkdir -p "$SLOTDIR"
    CURRENT_RUN=""; DONE_RUNS=" "; SLOT_RC=0; SLOT_SIGNAL=""; LP=""
    MY_RUNS="$(slot_runs "$SLOT")"
    trap 'slot_exit $?' EXIT
    trap 'SLOT_SIGNAL=SIGTERM; kill_launch; exit 143' TERM
    trap 'SLOT_SIGNAL=SIGINT; kill_launch; exit 130' INT
    slog "start, slot dir $SLOTREL"

    # node-level provenance, run ON the host through the launcher (profile_launch_on); checked against the request
    lrun profile_launch_on "$HOST" 1 1 "$C/scripts/node_prov.sh" "$SLOTDIR" "$HOST" > "$SLOTDIR/node_prov.out" 2>&1 < /dev/null
    nrc=$LRC
    NF="$SLOTDIR/node.prov"
    { [ "$nrc" -eq 0 ] && [ -s "$NF" ]; } || slot_abort "node provenance on $HOST failed (rc=$nrc, see $SLOTREL/node_prov.out)"
    if [ "${NODE_HOST_CHECK:-1}" = 1 ]; then
        want="${HOST%%.*}"; got="$(sed -n 's/^hostname=//p' "$NF")"; got="${got%%.*}"
        [ "$want" = "$got" ] || slot_abort "the launcher started slot $SLOT on '$got' instead of '$HOST'"
    fi

    # MKL probe on this host: first MKL_VERBOSE line of a tiny BLAS run, same launcher, same per-rank wrapper
    P="$SLOTDIR/mkl_probe"
    mkdir -p "$P"
    MKL_VERBOSE=1 lrun in_dir "$P" profile_launch_on "$HOST" "$RANKS" "$THREADS" "$C/scripts/rank_wrap.sh" probe "$P" $BLAS_PROBE_CMD \
        > "$P/out.txt" 2>&1 < /dev/null
    prc=$LRC
    mline="$(grep -E -m1 'MKL_VERBOSE.*(oneMKL|Intel\(R\) MKL|Math Kernel Library)' "$P/out.txt")"
    if [ -n "$mline" ]; then
        prov_mkl_parse "$mline"
    else
        MKL_VERSION="unavailable(probe rc=$prc, no MKL_VERBOSE version line)"; MKL_ISA="$MKL_VERSION"; MKL_THREADING="$MKL_VERSION"
    fi
    prov_kv "$NF" mkl_probe_rc "$prc"
    prov_kv "$NF" mkl_probe_line "${mline:-none}"
    prov_kv "$NF" mkl_version "$MKL_VERSION"
    prov_kv "$NF" mkl_isa "$MKL_ISA"
    prov_kv "$NF" mkl_threading "$MKL_THREADING"
    prov_kv "$NF" fakeintel_maps_probe "$(cat "$P"/rank_probe_*.prov 2>/dev/null | sed -n 's/^fakeintel_maps=//p' | sort -u | tr '\n' ' ')"
    if [ -z "$mline" ] && [ "${MKL_PROBE_REQUIRED:-1}" = 1 ]; then slot_abort "MKL probe gave no MKL_VERBOSE version line (rc=$prc)"; fi
    prov_mkl_threads_check "$THREADS" "$MKL_THREADING" || slot_abort "THREADS=$THREADS but the MKL threading layer is sequential"
    prov_mkl_check "$FAKEINTEL" "$MKL_ISA" || slot_abort "fakeintel=on but MKL took the $MKL_ISA path (need AVX-512): preload ineffective"
    TPC="$(sed -n 's/^threads_per_core=\([0-9][0-9]*\)$/\1/p' "$NF")"
    slog "MKL: $MKL_VERSION, $MKL_ISA, $MKL_THREADING; fakeintel=$FAKEINTEL"

    # the slot's provenance file = job-level part + this node's part (the runs of the slot point to it)
    SF="$SLOTDIR/job.prov"
    cp "$F" "$SF" || slot_abort "cannot copy the job provenance"
    while IFS= read -r line; do
        prov_kv "$SF" "${line%%=*}" "${line#*=}" || slot_abort "job and node provenance share a key: $line"
    done < "$NF"

    # ---- runs of this slot, one after the other ----
    while read -r rid scheme nd; do
        [ -n "$rid" ] || continue
        R="$C/runs/$rid"
        st="$(awk '{print $1; exit}' "$R/status" 2>/dev/null)"
        if [ "$st" = OK ]; then slog "skip $rid (status OK)"; DONE_RUNS="$DONE_RUNS$rid "; continue; fi
        n="$(ls -d "$R"/a[0-9]* 2>/dev/null | wc -l | tr -d ' ')"
        if [ "$n" -ge "$MAX_ATTEMPTS" ]; then
            slog "skip $rid ($n attempts >= MAX_ATTEMPTS=$MAX_ATTEMPTS, status $st)"; DONE_RUNS="$DONE_RUNS$rid "; continue
        fi
        k=$((n + 1)); while [ -e "$R/a$k" ]; do k=$((k + 1)); done
        A="$R/a$k"
        mkdir "$A" && cp "$R/input/parameters" "$R/input/seeds" "$A/" || slot_abort "cannot prepare $A"
        echo "a$k" > "$R/latest"
        CURRENT_RUN="$R"
        DONE_RUNS="$DONE_RUNS$rid "
        set_status "$R" "RUNNING job ${SLURM_JOB_ID:-} slot $SLOT a$k"
        f="$A/run.prov"
        prov_kv "$f" run_id "$rid"
        prov_kv "$f" attempt "a$k"
        prov_kv "$f" scheme_requested "$scheme"
        prov_kv "$f" n_delay_requested "$nd"
        prov_kv "$f" job_prov "$SLOTREL/job.prov"
        prov_kv "$f" slot "$SLOT"
        prov_kv "$f" slot_host "$HOST"
        prov_kv "$f" mkl_verbose_env "${MKL_VERBOSE:-unset}"
        prov_freq "$f" start
        prov_kv "$f" run_start "$(date '+%Y-%m-%dT%H:%M:%S%z')"
        slog "run $rid ($scheme, N_delay=$nd) attempt a$k"
        t0="$(prov_now)"
        lrun in_dir "$A" profile_launch_on "$HOST" "$RANKS" "$THREADS" "$C/scripts/rank_wrap.sh" alf "$A" "$BINARY" \
            > "$A/stdout.log" 2> "$A/stderr.log" < /dev/null
        rc=$LRC
        t1="$(prov_now)"
        prov_freq "$f" end
        prov_kv "$f" wall_s "$(awk -v a="$t0" -v b="$t1" 'BEGIN {printf "%.3f", b - a}')"
        res="1 s (date without %N)"; case "$t0" in *.*) res="1 ns (date +%s.%N)" ;; esac
        prov_kv "$f" wall_resolution "$res"
        prov_kv "$f" launch_rc "$rc"
        # max RSS over ranks (/usr/bin/time per rank), else sacct (job level), else unavailable
        rss=""; for r in "$A"/rss_*.txt; do
            v="$(prov_rss "$r" "$TIME_STYLE")"; [ -n "$v" ] && { [ -z "$rss" ] || [ "$v" -gt "$rss" ]; } && rss="$v"
        done
        if [ -n "$rss" ]; then src="/usr/bin/time ($TIME_STYLE), max over ranks"
        elif command -v sacct >/dev/null 2>&1 && [ -n "$SLURM_JOB_ID" ]; then
            rss="$(sacct -j "$SLURM_JOB_ID" -n -P -o MaxRSS 2>/dev/null | awk '{v=$1; m=1; if (v ~ /K$/) m=1; if (v ~ /M$/) m=1024; if (v ~ /G$/) m=1048576; sub(/[KMG]$/, "", v); if (v * m > x) x = v * m} END {if (x) printf "%d", x}')"
            src="sacct MaxRSS (job level, all steps so far)"
        fi
        [ -n "$rss" ] || { rss="unavailable(no /usr/bin/time output, no sacct)"; src="none"; }
        prov_kv "$f" max_rss_kb "$rss"
        prov_kv "$f" max_rss_source "$src"
        prov_kv "$f" rank_hosts "$(cat "$A"/rank_alf_*.prov 2>/dev/null | sed -n 's/^host=//p' | sort -u | tr '\n' ' ')"
        prov_kv "$f" rank_affinity_preinit "$(for p in "$A"/rank_alf_*.prov; do [ -r "$p" ] && printf 'r%s:%s ' "$(sed -n 's/^rank=//p' "$p")" "$(sed -n 's/^affinity=//p' "$p")"; done)"
        prov_kv "$f" fakeintel_maps "$(cat "$A"/rank_alf_*.prov 2>/dev/null | sed -n 's/^fakeintel_maps=//p' | sort -u | tr '\n' ' ')"
        prov_kv "$f" ld_preload "$(cat "$A"/rank_alf_*.prov 2>/dev/null | sed -n 's/^ld_preload=//p' | sort -u | tr '\n' ' ')"
        grep -h -E 'MPI startup\(\)|cpu-bind|cpu_bind' "$A/stdout.log" "$A/stderr.log" > "$A/pin_map.txt" 2>/dev/null
        n="$(wc -l < "$A/pin_map.txt" | tr -d ' ')"
        if [ "$n" -gt 0 ]; then v="$n lines in pin_map.txt; first: $(head -1 "$A/pin_map.txt")"
        else v="unavailable(no I_MPI_DEBUG / cpu-bind lines)"; fi
        prov_kv "$f" pin_map "$v"
        pin="$(prov_pin_check "$A/pin_map.txt" "$RANKS" "$THREADS" "${TPC:-1}")"; pinrc=$?
        prov_kv "$f" pin_check "$pin"
        cat "$A/stdout.log" "$A/stderr.log" "$A"/rss_*.txt 2>/dev/null | grep '^OMP_AFFINITY' > "$A/omp_affinity.txt"
        n="$(wc -l < "$A/omp_affinity.txt" | tr -d ' ')"
        if [ "$n" -gt 0 ]; then v="$n lines in omp_affinity.txt; first: $(head -1 "$A/omp_affinity.txt")"
        else v="none printed (no OpenMP parallel region was entered)"; fi
        prov_kv "$f" omp_affinity "$v"
        reason=""
        if [ "$rc" -ne 0 ]; then reason="launcher rc=$rc"
        elif [ ! -s "$A/info" ]; then reason="no info file"
        elif ! grep -q '^ *CPU Time *:' "$A/info"; then reason="no CPU Time line in info (run incomplete)"
        elif [ "$scheme" != standard ] && ! grep -q -F "Sequential scheme: $(printf '%s' "$scheme" | tr '[:lower:]' '[:upper:]')" "$A/info"; then
            reason="info has no 'Sequential scheme: $scheme' line (scheme not active)"
        fi
        if [ -n "$reason" ]; then status="FAILED rc=$rc $reason"; SLOT_RC=1
        elif [ "$pinrc" -ne 0 ]; then status="INVALID pinning: $pin"; SLOT_RC=1
        else status="OK"; fi
        prov_kv "$f" status "$status"
        set_status "$R" "$status"
        CURRENT_RUN=""
        slog "run $rid: $status"
    done <<EOF
$MY_RUNS
EOF
    exit "$SLOT_RC"
}

SLOTS_STARTED=1
i=0
for host in $HOSTS; do
    [ "$i" -lt "$NSLOTS" ] || break
    run_slot "$i" "$host" &
    SLOT_PIDS="$SLOT_PIDS $!"
    i=$((i + 1))
done
log "started $i slots (pids$SLOT_PIDS); waiting"
wait_slots
# job rc: 0 only if every slot finished with rc 0 (a failed run or an aborted slot: 1)
i=0
while [ "$i" -lt "$NSLOTS" ]; do
    [ "$(cat "$JOBDIR/slot_$i/slot.rc" 2>/dev/null)" = 0 ] || JOB_RC=1
    i=$((i + 1))
done
exit "$JOB_RC"
